// 酒馆助手只启用此入口。索拉里斯补丁与原作者源码分别维护。
const UPSTREAM_URL = 'https://cdn.jsdelivr.net/gh/tangquanghuy/dnf@latest/dist/V20261015/external-status-bar.js?v=1';
const PATCH_URL = 'https://cdn.jsdelivr.net/gh/qq85316902-cloud/tga-wuwa@41018efd167c7d5e7010d68c2231d97c83754046/dist/solaris-patch.json';
const host = window.parent || window;
const KEY = '__solarisStatusController';
if (host[KEY]?.dispose) host[KEY].dispose();
let disposed=false, frame=null, active='', busy=false, retryAt=0, original='', patch=null;
const api={loaderVersion:'2026.10.26.1',storyDeliveryVerified:true,oneActiveMain:true,storyStartConfirmation:true,mode:'loading', error:'', upstreamUrl:UPSTREAM_URL, dispose};
host[KEY]=api;
const pause=ms=>new Promise(resolve=>setTimeout(resolve,ms));
const world=()=>{
  for(const win of [host,window])try{
    const raw=win.Mvu?.getMvuData?.({type:'message',message_id:'latest'}) ?? win.getVariables?.({type:'message',message_id:'latest'});
    const value=(raw?.stat_data||raw)?.系统配置?.世界观;
    if(value)return String(value).trim();
  }catch{}
  return '';
};
function notice(message){console.warn('[索拉里斯扩展]',message);host.toastr?.warning?.(message,'索拉里斯状态栏');}
async function read(url){const r=await fetch(url,{cache:'no-cache'});if(!r.ok)throw new Error(`下载失败 (${r.status})`);return r.text();}
function applyPatch(source, manifest){
  if(!Array.isArray(manifest?.patches)||!manifest.patches.length)throw new Error('扩展补丁为空');
  let out=source.replace(/\r\n/g,'\n');
  for(let i=0;i<manifest.patches.length;i++){
    const {before,after}=manifest.patches[i];
    if(typeof before!=='string'||!before||typeof after!=='string')throw new Error('扩展补丁格式错误');
    const pos=out.indexOf(before);
    if(pos<0||out.indexOf(before,pos+before.length)>=0)throw new Error(`原版结构变化，补丁 ${i+1} 无法安全应用`);
    out=out.slice(0,pos)+after+out.slice(pos+before.length);
  }

  const enemyNameCorrections=[["无音区强敌已被实际击败","无冠者已被实际击败"],["迎战强大残象并将其击溃","迎战无冠者并将其击溃"],["无音区内外分隔战斗者与观察者","无音区内外分隔无冠者战的参战者与观察者"],["利用机械敌人的关节与掉落部件将其击败","利用聚械机偶的关节弱点与掉落部件将其击败"],["地下机械敌人已击败","地下的聚械机偶已击败"],["伤痕及其异生梦魇","伤痕及其异化形态“伤痕·异生梦魇”"],["伤痕及异生梦魇的冲突","伤痕与“伤痕·异生梦魇”阶段的冲突"],["游鳞机枢被击败","游鳞机枢·凛铓被击败"],["游鳞机枢已击败","游鳞机枢·凛铓已击败"],["蚀脊龙暴君","蚀脊龙·「暴君」"],["伪作神王","伪作的神王"],["疯王卡利古拉","疯王·卡利古拉"],["击败免疫般攻击隧群","击败炉芯机骸（炉芯上具有免疫系统般攻击行为的隧群）"],["击败强敌救回秧秧","击败万囮牢救回秧秧"],["万囮牢屏障及强敌已解决","万囮牢已被击败、相应屏障已解除"],["万囮牢旁","万囮牢所在处"],["两度迎战天傀，","两度迎战天傀劫煞，"],["两战破天傀，","两战击败天傀劫煞，"],["木禺天傀被击败","木禺所附的天傀劫煞被击败"],["木禺弃肉身后仍有天傀战力","木禺弃肉身后仍以天傀劫煞形态作战"],["协力击败心魔、回收错误星图","协力击败星图核心（心魔）、回收错误星图"],["已会合并击败心魔核心","已会合并击败星图核心（心魔）"],["击败镜中自己","击败镜中的“珂莱塔”"],["处理逐渐增强的敌人","迎战残象；前段夺回星星时，与大布偶、铲子叔叔、寂寞小姐、魔术先生等布偶交战"],["敌人显出亚当·重锤形象","敌人显出梦魇亚当·重锤形象"],["梦魇在终点阻拦","梦魇亚当·重锤在终点阻拦"],["迎击梦魇是同一高潮","击败梦魇亚当·重锤是同一高潮"],["终点威胁已解除","终点的梦魇亚当·重锤已被击败"]];
  for(const [before,after] of enemyNameCorrections)out=out.split(before).join(after);
  return out;
}
function clearInstance(){
  if(frame){try{frame.contentWindow?.rpg_status_bar_cleanup?.();}catch{}frame.remove();frame=null;}
  host.document.getElementById('solaris-atlas-overlay')?.querySelector('button')?.click();
  for(const id of ['rpg_status_bar-toggle','rpg_status_bar-panel','rpg_status_bar-styles'])host.document.getElementById(id)?.remove();
  for(const suffix of ['cleanup','showPopup','SkillIcons','GameIcons','fetchData','refresh','setState','openTab','setTheme','setAppearance'])delete host['rpg_status_bar_'+suffix];
  host.__状态栏_loaded__=false;
}
function addStoryStartConfirmation(source){
  const before = "          if(replay){showPanelConfirm('<strong class=\"scenario-confirm-title\">'+(replay?'重新执行':'接取')+'《'+escapeScenarioHtml(name)+'》？</strong><span class=\"scenario-confirm-detail\">'+detail+'</span>',()=>replay?restartScenarioEntry(kind,name):activateScenarioEntry(kind,name));}else{activateScenarioEntry(kind,name).catch(error=>{log.error('索拉里斯接取失败',error);showToast('error','接取失败：'+error.message);});}";
  const after = "          showPanelConfirm('<strong class=\"scenario-confirm-title\">'+(replay?'重新执行':'确定开启')+'《'+escapeScenarioHtml(name)+'》？</strong><span class=\"scenario-confirm-detail\">'+detail+'<br>确认后发送：<b>'+escapeScenarioHtml(actionText)+'</b></span>',()=>{\n            const action=replay?restartScenarioEntry(kind,name):activateScenarioEntry(kind,name);\n            Promise.resolve(action).catch(error=>{log.error('索拉里斯接取失败',error);showToast('error','接取失败：'+error.message);});\n          });";
  if(!source.includes(before)){
    if(source.includes("if(kind.startsWith('solaris')) {")) throw new Error('剧情开启确认补丁未匹配，请更新状态栏');
    return source;
  }
  if(source.split(before).length!==2) throw new Error('剧情开启确认补丁匹配不唯一');
  return source.replace(before,after);
}
const SOLARIS_STORY_FALLBACK={"END_MANIFEST":{"鸣潮副本":{"M01-万象新声·上":[{"id":"S01_C01","text":"01-万象新声·上篇：无冠者已被实际击败，同行者已脱离本次封锁与直接危险。"},{"id":"S01_C02","text":"01-万象新声·上篇：肉身纳骸的异常已发生并被同行者观察到；身份原因仍保留为待查。"},{"id":"S01_C03","text":"01-万象新声·上篇：今汐的寻客留言已经收到，赴今州的行动方向已确定并开始离开云陵谷。"},{"id":"S02_C01","text":"02-万象新声·下篇：坚岩斗士的复现实验已经结束，并确认此次没有再次触发肉身纳骸。"},{"id":"S02_C02","text":"02-万象新声·下篇：普通声骸已用终端完成回收、装配或等效功能验证。"},{"id":"S02_C03","text":"02-万象新声·下篇：队伍实际抵达今州城前，边庭接待与研究院检查的下一步分工已明确。"},{"id":"S03_C01","text":"03-嘤鸣初相召篇：边庭信物和相应权限已经领取，研究院的检查实际完成。"},{"id":"S03_C02","text":"03-嘤鸣初相召篇：日晷配件、紫叶检测结果、糖丸关联的旧战档案已取得，三条线索均有调查结果。"},{"id":"S03_C03","text":"03-嘤鸣初相召篇：本轮信物结论已汇总，队伍已经离院休息；不是只约定稍后检测。"}],"M02-撞金止行阵":[{"id":"S01_C01","text":"04-撞金止行阵篇：侦查塔风波已解决，塔的监测功能得到恢复，伤兵接应已完成。"},{"id":"S01_C02","text":"04-撞金止行阵篇：致远已找到，其随军风险与后续去向已经处理，鉴心决定留营帮助今州。"},{"id":"S01_C03","text":"04-撞金止行阵篇：莽吉柿调查和战场幻视已告一段落，漂泊者与秧秧明确转查紫叶及祈池村。"},{"id":"S02_C01","text":"05-奔策候残星篇：祈池村现场证据与伤痕的招揽已经经历，来客已突破伤痕幻境并与秧秧重新会合。"},{"id":"S02_C02","text":"05-奔策候残星篇：退水通路已开启，女孩的日记已找到并读出村长控制她的关键事实。"},{"id":"S02_C03","text":"05-奔策候残星篇：村庄悲剧的调查结论已形成，二人携证据返城或已安排上报；未把伤痕寓言当唯一真相。"},{"id":"S03_C01","text":"06-庭际刀刃鸣篇：日晷与数据库通道已经解开，今汐的秘密会面内容已通过实际会面或回叙交付。"},{"id":"S03_C02","text":"06-庭际刀刃鸣篇：伤痕与“伤痕·异生梦魇”阶段的冲突已结束，伤痕已被拘捕，审讯情报已取得。"},{"id":"S03_C03","text":"06-庭际刀刃鸣篇：漂泊者转查黑花、今汐前往寻角的分途安排已经落实；不是仍停在准备设伏。"}],"M03-欲知天将雨":[{"id":"S01_C01","text":"07-欲知天将雨篇：黑花调查已引出黑海岸人员，漂泊者已与秋水、安可建立本次调查合作。"},{"id":"S01_C02","text":"07-欲知天将雨篇：稷廷实验室的关键记录已查明，地下的聚械机偶已击败，数据信标调查已有结果。"},{"id":"S01_C03","text":"07-欲知天将雨篇：今州遭残象潮攻击的警报已收到，队伍已结束遗址调查并转入返城应战。"},{"id":"S02_C01","text":"08-千里卷戎旌篇：今州前哨支援与被困士兵救援已落实，主力没有仍困在尚未处理的城防危机中。"},{"id":"S02_C02","text":"08-千里卷戎旌篇：漂泊者已与忌炎会合、击败云闪之鳞，突入鸣式核心的部署已确定。"},{"id":"S02_C03","text":"08-千里卷戎旌篇：凿空炮台的救援、能源接口修复及充能防守已完成，炮台已具备支援突入的条件。"},{"id":"S03_C01","text":"09-千里卷戎旌篇：队伍已突破峡谷和悬浮废墟，炮击开路与同伴断后已实际完成。"},{"id":"S03_C02","text":"09-千里卷戎旌篇：无冠者重组、月亮核心及无妄者的战斗已解决，无妄者被击败并按本线结果处理。"},{"id":"S03_C03","text":"09-千里卷戎旌篇：队伍已撤出崩塌的天悬烽火，鸣式逃离与无妄者败亡的结果已分别说明。"},{"id":"S04_C01","text":"10-千里卷戎旌篇：北落野战斗已结束，街头战后说书及岳辉相认的交谈已实际发生。"},{"id":"S04_C02","text":"10-千里卷戎旌篇：漂泊者已听到民间传唱与居民对雨停的反应，本段战后安宁已收束；不要求新增战斗。"},{"id":"S05_C01","text":"11-行路遇新知篇：伙伴已经在攀花饭馆重聚，对体内出现的小家伙有过实际交流。"},{"id":"S05_C02","text":"11-行路遇新知篇：阿布的称呼、同行身份和待查能力已说明，聚餐已结束并进入数日后的过渡。"}],"M04-梦境遗尘":[{"id":"S01_C01","text":"12-梦境遗尘篇：梦境、阿布异常频率与乘霄山线索已引向边庭求证。"},{"id":"S01_C02","text":"12-梦境遗尘篇：散华已说明今汐失联及保密要求，漂泊者已决定赴渡口并离开边庭。"},{"id":"S02_C01","text":"13-远赴乘霄篇：与长离完成渡口会合，入山风险与同行选择已经交代。"},{"id":"S02_C02","text":"13-远赴乘霄篇：隙光滩溯流仪、撷光锁及残星会伏击已解决，二人实际穿过时流结界。"},{"id":"S02_C03","text":"13-远赴乘霄篇：队伍已抵达虹镇，不是只看到远处镇子或刚开始赶路。"},{"id":"S03_C01","text":"14-山间古镇篇：虹镇空镇痕迹已调查，瀑后避难所已进入并与辛夷及镇民取得联系。"},{"id":"S03_C02","text":"14-山间古镇篇：已确认今汐救人后先行、取心核才能开启眠龙庭的因果关系。"},{"id":"S03_C03","text":"14-山间古镇篇：镇民已有避难安排，漂泊者与长离已开始前往叩天关。"},{"id":"S04_C01","text":"15-叩天关篇：叩天关三层曜岩的封锁已解除，取得心核所需的路径条件已具备。"},{"id":"S04_C02","text":"15-叩天关篇：关于角缺频、时流孤岛及二次共鸣方案的关键卷宗已查明，并与今汐会合。"},{"id":"S04_C03","text":"15-叩天关篇：游鳞机枢·凛铓已击败，通向心核的道路已实际打开；本章尚不要求提前取得下一章心核。"},{"id":"S05_C01","text":"16-朝觐之路篇：心核已从中枢窟室取出，长离断后与二人离关的分工已经落实。"},{"id":"S05_C02","text":"16-朝觐之路篇：辛夷已将心核用于机枢，眠龙庭的入口已开启。"},{"id":"S05_C03","text":"16-朝觐之路篇：漂泊者与今汐已进入眠龙庭并确认角仍无回应，当前目标转为解除禁锢。"},{"id":"S06_C01","text":"17-眠龙庭篇：眠龙庭机关路径已恢复，三处曜岩已经处理、特殊曜纹全部熄灭。"},{"id":"S06_C02","text":"17-眠龙庭篇：残星会禁锢角的力场已解除，二人实际返回舱体前准备当面对话。"},{"id":"S07_C01","text":"18-时序之主篇：角已向二人解释时序死局，今汐的承担与婴儿旧事已在对话中明确。"},{"id":"S07_C02","text":"18-时序之主篇：声之领域中的命定之战已经实际结束，今汐完成意志与能力的证明。"},{"id":"S07_C03","text":"18-时序之主篇：御者权限请求与回应已落实，时序之能已让渡今汐；只提出让渡方案不算完成。"},{"id":"S08_C01","text":"19-风消雪霁篇：乘霄山时流已回正，今汐安全及返城休养安排已确认。"},{"id":"S08_C02","text":"19-风消雪霁篇：虹镇人的留山寿数条件已说明，漂泊者已完成与角的事后交流并返向虹镇。"},{"id":"S08_C03","text":"19-风消雪霁篇：乘霄山危机的当前结果已收束；不要求来客知晓残星会幕后镜头。"}],"M05-月下祈愿其一·倾听之音":[{"id":"S01_C01","text":"20-月下祈愿其一·倾听之音篇：第一封受污染心愿已解码，并查明晓声对应十番而非仅靠同名猜测。"},{"id":"S01_C02","text":"20-月下祈愿其一·倾听之音篇：十番与九离已经直接沟通，事故、自责与被责怪的关键误解已说开。"},{"id":"S01_C03","text":"20-月下祈愿其一·倾听之音篇：心愿已得到本人和朋友的回应，第一阶段祈愿摊筹备已有落实或明确交接记录。"},{"id":"S02_C01","text":"21-月下祈愿其二·老人与约定篇：禾盈的心愿已读出，修远的生平与老人的悲伤已通过倾听实际了解。"},{"id":"S02_C02","text":"21-月下祈愿其二·老人与约定篇：节日游逛及修远留下的手册、手艺或教导影响已呈现给禾盈。"},{"id":"S02_C03","text":"21-月下祈愿其二·老人与约定篇：禾盈已表达愿意继续面对生活的当下选择，第二阶段筹备已有交接；不要求她立刻不再悲伤。"},{"id":"S03_C01","text":"22-月下祈愿其三·幼小的英雄梦篇：小满的心愿、秘密基地与模仿修炼的去向已查明。"},{"id":"S03_C02","text":"22-月下祈愿其三·幼小的英雄梦篇：山洞残象已处理，小满已经脱离直接危险并得到返回伙伴处的安排。"},{"id":"S03_C03","text":"22-月下祈愿其三·幼小的英雄梦篇：英雄不等于立刻觉醒共鸣力的引导已完成，小满已答应参加宵月会。"},{"id":"S04_C01","text":"23-月下祈愿其四·筹备篇：小帕索诺拉已进入，相里要父亲及帕斯卡研究困境的关键回声已被理解。"},{"id":"S04_C02","text":"23-月下祈愿其四·筹备篇：偏执合集已击败，帕斯卡频谱由残存笔记重建并用于研究、原型机尚未重造成功及其并未主动制造海蚀的真相已交代；遗留心意与成果传承已传达，队伍已返回现实。"},{"id":"S04_C03","text":"23-月下祈愿其四·筹备篇：相里要完成必要的独处和事后沟通，宵月会已到来并与伙伴合影；不能刚出索诺拉就跳过节日收尾。"}],"M06-来自毁灭的回声":[{"id":"S01_C01","text":"24-来自毁灭的回声篇：归墟港市指定坐标与灾难残响已调查，失联执花死亡已确认并安排遗体处理。"},{"id":"S01_C02","text":"24-来自毁灭的回声篇：HL-1的异常读数已发现，并保留装置可能受骗的疑点，不擅自认定岁主死亡。"},{"id":"S01_C03","text":"24-来自毁灭的回声篇：桥下异变已经发生，神秘接引者已将漂泊者引向黑海岸。"},{"id":"S02_C01","text":"25-沉匿于海浪之间的是篇：漂泊者已抵达黑海岸，专用信标已启用，与外界报平安的联络已完成。"},{"id":"S02_C02","text":"25-沉匿于海浪之间的是篇：新枝地、阿斯特莉亚之眼、移转异象所的稳定锚修复已完成。"},{"id":"S02_C03","text":"25-沉匿于海浪之间的是篇：霍德关于亡者处境的线索与守岸人相认已经发生，地下调查入口已具备。"},{"id":"S03_C01","text":"26-亘古永夜的孑遗篇：地下机器人救援及通路、密钥、污染障碍已处理，已接触收容中的噬亡星。"},{"id":"S03_C02","text":"26-亘古永夜的孑遗篇：噬亡星逸出数据已制压，奇点核心已实际取得。"},{"id":"S03_C03","text":"26-亘古永夜的孑遗篇：守岸人本体与虚影的状态已明确，来客已抵调律大厅外并击退聚集残象。"},{"id":"S04_C01","text":"27-若能在过去夺回明天篇：核心已放入调律流程，归墟星图内的城市毁灭记录与霍德质问已实际经历。"},{"id":"S04_C02","text":"27-若能在过去夺回明天篇：守岸人被卷入核心的结果已确认，常规调律未能救回她。"},{"id":"S04_C03","text":"27-若能在过去夺回明天篇：旧日志、黑花及调律者已恢复来客管理员权限，救援方案得到成员支持并具备深入系统的条件。"},{"id":"S05_C01","text":"28-便能在如今走向未来篇：漂泊者已实际突破泰缇斯内部防卫，抵达数据中枢洪流。"},{"id":"S05_C02","text":"28-便能在如今走向未来篇：无归的谬误已击败，守岸人已经从编码核心中救回。"},{"id":"S05_C03","text":"28-便能在如今走向未来篇：沙滩重逢与旧循环代价的事后交流已完成，亡者与守岸人的当前结果已说明。"},{"id":"S06_C01","text":"29-海岸尽头……之后？篇：本章发生在守岸人获救之后，战后等待已满足，双方已经在花房重逢。"},{"id":"S06_C02","text":"29-海岸尽头……之后？篇：阿布检索、替代底层频率及未来同行的交谈已完成；不以再次修复系统为结束要求。"}],"M07-如一叶小舟穿行于茫茫海洋":[{"id":"S01_C01","text":"30-如一叶小舟穿行于茫茫海洋篇：黑海岸的旧信息、阿布调查进展与莫塔里邀请已交付，出海行动实际开始。"},{"id":"S01_C02","text":"30-如一叶小舟穿行于茫茫海洋篇：海上残象危机已解决，漂泊者已与愚人剧团接触并到达拉古那港。"},{"id":"S01_C03","text":"30-如一叶小舟穿行于茫茫海洋篇：入境时阿布、终端和声骸的审查插曲已处理，菲比已引导来客进入城内。"},{"id":"S02_C01","text":"31-那神圣微风时常吹入篇：资助领取和赞妮护卫关系已建立，餐厅失控刀伶已被制止并留下求助线索。"},{"id":"S02_C02","text":"31-那神圣微风时常吹入篇：胶片、面具店与家族动向已调查，吉尔贝和教堂往来的线索已落实。"},{"id":"S02_C03","text":"31-那神圣微风时常吹入篇：二人已穿过后花园、抵达忏悔室隐秘通路；不以只怀疑修会结束调查段。"}],"M08-夜与昼，均请摘下面纱":[{"id":"S01_C01","text":"32-夜与昼，均请摘下面纱篇：失踪声骸与污染线索已查明，菲比已加入，罗蕾莱受控及云海威胁已明确。"},{"id":"S01_C02","text":"32-夜与昼，均请摘下面纱篇：云中庭院入口已由圣女咏叹调开启，噩梦中的罗蕾莱已击败并恢复使命。"},{"id":"S01_C03","text":"32-夜与昼，均请摘下面纱篇：云海当前危机已暂止，狂欢节集体祈愿与誓约仪式的沟通条件已告知。"},{"id":"S02_C01","text":"33-夜与昼，均请摘下面纱篇：金库分路潜入及关键安保障碍已完成，两人已会合并取得调音师证词。"},{"id":"S02_C02","text":"33-夜与昼，均请摘下面纱篇：私人终端愿景、声骸彩窗与废弃高塔线索已调查，少女神启者预言已复原。"},{"id":"S02_C03","text":"33-夜与昼，均请摘下面纱篇：修会阻截已实际应对，漂泊者已从高塔冲突脱身并转往悲叹墓岛。"}],"M09-昔我悲伤，今却歌唱":[{"id":"S01_C01","text":"34-昔我悲伤，今却歌唱篇：已在墓岛与洛可可及布兰特会合，朝圣船的危险已查明，叹息古龙已击败并实施救援。"},{"id":"S01_C02","text":"34-昔我悲伤，今却歌唱篇：造云机已修复，巴多里奥的升空事故已处理，队伍实际回到剧团据点。"},{"id":"S01_C03","text":"34-昔我悲伤，今却歌唱篇：珂莱塔与剧团已达成演出合作，序幕彩排已完成并约好返城准备。"},{"id":"S02_C01","text":"35-昔我悲伤，今却歌唱篇：狂欢节舞台的赫卡忒战斗已结束，溯海之鲸已摆脱控制、会场人员安全已有结果，演出完成，漂泊者实际获得桂冠。"},{"id":"S02_C02","text":"35-昔我悲伤，今却歌唱篇：狂欢顶点已与卡提希娅接触，倒悬高塔的指引已获得。"},{"id":"S02_C03","text":"35-昔我悲伤，今却歌唱篇：次日芬莱克会面及离教堂后的复盘已完成，剧团获得进入拉古那永久演出资格的结果已交付，圣女双重身份矛盾与后续调查方向已明确。"}],"M10-叶落无声":[{"id":"S01_C01","text":"35A-叶落无声篇：已完成金库接头与护送介入，分层权限、安全模块被取走及冒名者与老艾许的区别已通过调查明确。"},{"id":"S01_C02","text":"35A-叶落无声篇：研究者居住区、名册或残响的调查已完成，书页声骸的0622密码门已开启，队伍已经到达后续通路而非仍困在坠车处。"},{"id":"S01_C03","text":"35A-叶落无声篇：最终站危机中嫌疑人、安全模块及解除封锁的实际处理结果均已记录，队伍已安全脱困；源文缺失不能直接视为自动成功。"},{"id":"S01_C04","text":"35A-叶落无声篇：赞妮关于树与炸弹的调查结论、向珂莱塔汇报的结果，以及菲比目送与反思的事后交流已交付。"}],"M11-老人鱼海":[{"id":"S01_C01","text":"35B-老人鱼海篇：裴魁德号已修复，风暴碑文已解，队伍已实际登上莱耶斯最后的小岛。"},{"id":"S01_C02","text":"35B-老人鱼海篇：三处馈赠与幽灵谜题已处理，莱耶斯灯塔已点亮，并完成鲸与海妖关系调查；四塔齐明时，前三塔可依所供文本作为明确入场背景，不自动登记玩家亲历、通关或奖励；另行改写的此前航海按实际结果承接。"},{"id":"S01_C03","text":"35B-老人鱼海篇：亚哈留言及斯塔巴克斯独自出航的情况已查明，裴魁德号已进入风暴并完成本次实际危机处置与队伍安全收束，不用原文缺失替代行动。"},{"id":"S01_C04","text":"35B-老人鱼海篇：休整后的小岛会面已完成，阿布翻译确认鲸的康复与海妖吸收残响的事实，菲比已作个人道歉并得到鲸的回应。"}],"M12-圣者，忤逆者，告死者":[{"id":"S01_C01","text":"36-圣者，忤逆者，告死者篇：拯救、联结、向上三塔的剑与石座机制已完成，卡提希娅分离自身和寄放力量的旧事已揭明。"},{"id":"S01_C02","text":"36-圣者，忤逆者，告死者篇：圣授厅的芙露德莉斯战斗已解决，来客与卡提希娅完成共同选择而非仅接受自毁方案。"},{"id":"S01_C03","text":"36-圣者，忤逆者，告死者篇：英白拉多的旧约、根权限计划、同一个体同时仅一位共鸣者的限制及坎特蕾拉割舍二次共鸣的选择已揭明；岁主以最后力量救回卡提希娅，她保留记忆与自身的选择已交付，阿布稳定，众人回地面完成善后交流。"}],"M13-荣耀暗面":[{"id":"S01_C01","text":"37-荣耀暗面篇：阿维纽林失联线索已确认，漂泊者已经进入七丘并与露帕组队。"},{"id":"S01_C02","text":"37-荣耀暗面篇：特别选拔赛的伏尔甘矿业与缥浪已击败，冠军赛参赛资格已取得。"},{"id":"S01_C03","text":"37-荣耀暗面篇：城区与特库斯水域的寻人调查已有结果，未能联结卡提希娅的现状已明确。"},{"id":"S02_C01","text":"38-荣耀暗面篇：弗洛洛三日剧本的威胁已经交付，漂泊者没有把预言当作已发生事实。"},{"id":"S02_C02","text":"38-荣耀暗面篇：半决赛繁枝获胜及铜镜里的蜜芽旧事已实际经历，家族操控线索已揭出。"},{"id":"S02_C03","text":"38-荣耀暗面篇：血色决赛和受控亚狮诺索的战斗已结束，二人夺冠并见到剧作家现形；尚未提前结算荣耀之间终局。"},{"id":"S03_C01","text":"39-燃烧的心篇：荣耀古道、露帕主动追查及铜镜实验记录已交付，杀死露帕的诱导陷阱已识破。"},{"id":"S03_C02","text":"39-燃烧的心篇：海之女及覆盖现实的计划已被实际制止，露帕与卡提希娅均已确认脱险。"},{"id":"S03_C03","text":"39-燃烧的心篇：多轮经历已互通，岩间中枢缺频和卡提希娅需检查的后续方向已明确。"}],"M14-捕梦于神秘园中":[{"id":"S01_C01","text":"40-捕梦于神秘园中篇：黑海岸已报告卡提希娅失衡、残存鸣式频率与目标坐标，出海准备已落实。"},{"id":"S01_C02","text":"40-捕梦于神秘园中篇：漂泊者已经驶向指定海域，并与芬莱克引出的新计划正面接触。"},{"id":"S02_C01","text":"41-捕梦于神秘园中篇：隐海试验场的封锁处境与宝石争夺已查明，和弗洛洛的临时合作已实际建立。"},{"id":"S02_C02","text":"41-捕梦于神秘园中篇：外层调律台、轨道和修会封锁已突破，队伍已经进入声骸制造设施核心区。"},{"id":"S03_C01","text":"42-捕梦于神秘园中篇：公共声骸制造与破碎频率的现场已调查，故人声音对弗洛洛的影响已呈现。"},{"id":"S03_C02","text":"42-捕梦于神秘园中篇：本区调律已完成，监视录音已取得，二人已离开当前台继续深入。"},{"id":"S04_C01","text":"43-捕梦于神秘园中篇：已确认整座试验场由核心乐曲控制，芬莱克藏起两段曲谱。"},{"id":"S04_C02","text":"43-捕梦于神秘园中篇：缺谱所在的下层路线已定位并实际进入培育舱；本章不要求提前拿到下一章的两段谱。"},{"id":"S05_C01","text":"44-捕梦于神秘园中篇：双方分路找谱与借指挥棒协助已实际完成，两段缺失曲谱均已追回。"},{"id":"S05_C02","text":"44-捕梦于神秘园中篇：能源系统拦截已突破，合谱后的调律已恢复。"},{"id":"S05_C03","text":"44-捕梦于神秘园中篇：巨大索诺拉代价与双方最终争宝石的分歧已明确，队伍已沿输能管道继续前行。"},{"id":"S06_C01","text":"45-捕梦于神秘园中篇：已通过朝拜区域，来客已经进入并调查失亡彼岸的音乐会与研究记录。"},{"id":"S06_C02","text":"45-捕梦于神秘园中篇：故乡毁灭、残响不等于完整复生及弗洛洛合作网络已通过线索揭明。"},{"id":"S06_C03","text":"45-捕梦于神秘园中篇：音乐会相见与对话已经结束，确认宝石不在彼岸，二人实际再次合流追击芬莱克。"},{"id":"S07_C01","text":"46-捕梦于神秘园中篇：芬莱克代行者冲突已结束，其留守封潮、巡游天国警示及转查七丘的线索已交代；最终命运留待后续确认。"},{"id":"S07_C02","text":"46-捕梦于神秘园中篇：宝石被残星会回收、弗洛洛沉海失踪的去向已确认，没有误报夺回宝石。"},{"id":"S07_C03","text":"46-捕梦于神秘园中篇：下一步赴七丘与总督会面的安排已确定；可选重访彼岸不列为必须完成的任务。"}],"M15-铁锈，剑与烈阳":[{"id":"S01_C01","text":"47-铁锈，剑与烈阳篇：烈日酒馆的涅索叙诗已经听完，训练、三道试炼及少女获承认的主线经历已交付。"},{"id":"S01_C02","text":"47-铁锈，剑与烈阳篇：奥古斯塔为何托剑七丘及依靠个人力量维系规则的隐患已呈现，叙事已返回现实会面前。"},{"id":"S02_C01","text":"48-灼我以烈阳篇：总督邀约与狩原会合已经完成，三处定向锚的围猎方案已实际执行。"},{"id":"S02_C02","text":"48-灼我以烈阳篇：暴君反击与追踪已推进至更大威胁显露，确认它并非源头终点。"},{"id":"S02_C03","text":"48-灼我以烈阳篇：尤诺的消耗及休息安排已落实，队伍已经转向伪作的神王与呓语镇。"},{"id":"S03_C01","text":"49-灼我以烈阳篇：呓语镇与旧日索诺拉调查已完成，纯净黑潮样本已取得并用于定位伪王。"},{"id":"S03_C02","text":"49-灼我以烈阳篇：彻地之楔的伪作的神王已被实际击败，奥古斯塔没有将意志交给低语。"},{"id":"S03_C03","text":"49-灼我以烈阳篇：英白拉多遗匣已取得、当前尚不能开启；求助黑海岸或联系卡提希娅的后续方向已明确，尤诺尚未结清的代价被保留。"}],"M16-今夜，注定属于月亮":[{"id":"S01_C01","text":"50-今夜，注定属于月亮篇：已发现众人不记得尤诺的异常，四方殿记录与来客记忆冲突已查证。"},{"id":"S01_C02","text":"50-今夜，注定属于月亮篇：来客在混沌中与尤诺重新建立联系，并走过她的选择、月石金枝锚定及最后救援。"},{"id":"S01_C03","text":"50-今夜，注定属于月亮篇：尤诺已在现实庆典重现并与来客重逢，花雨蜜酒中的团聚已完成；不能只在混沌中见面便判救回。"}],"M17-已逝的必将归来":[{"id":"S01_C01","text":"51-已逝的必将归来篇：拉古那噩梦、金库黑潮造物与文明之匣的调查已完成，匣内记录已交付且队伍安全撤出。"},{"id":"S01_C02","text":"51-已逝的必将归来篇：狄萨莱海脊救援及阿维狄亚疯王冲突已处理，本轮黑潮暂受遏制。"},{"id":"S01_C03","text":"51-已逝的必将归来篇：真正代行者是漂泊者的揭示已发生，并明确必须处理其体内侵蚀与天国威胁。"},{"id":"S02_C01","text":"52-暗潮将映的黎明篇：两城与黑海岸联合、锚定界石防线及通往天国的路径已建立。"},{"id":"S02_C02","text":"52-暗潮将映的黎明篇：嘉贝莉娜旧路、卡提希娅潜入真相及克里斯托弗幻境已突破，同伴精神锚点已会合。"},{"id":"S02_C03","text":"52-暗潮将映的黎明篇：鸣式之茧及利维亚坦终战已结束，威胁受束缚，宝石已由黑海岸收容。"},{"id":"S02_C04","text":"52-暗潮将映的黎明篇：两城救治与重建安排、将已空白的岁主遗物交予菲比及港口送别已完成；残缺频率和残星会后续仍列待查，可选方舟合作不要求工程建成。"}],"M18-独在异乡为异客":[{"id":"S01_C01","text":"53-独在异乡为异客篇：夏空补述的仇远参战、明庭委托与炬火指引、假利奥所涉梁东园血债线索、哥舒临早年受诬回忆及芬莱克意识托灯安息经过已交付，已标明旧战回叙与各自来源，未将未解身份坐实。"},{"id":"S01_C02","text":"53-独在异乡为异客篇：漂泊者已在港口见到仇远，关于哥舒临的有限信息已交流并完成告别。"}],"M19-曙光停摆于荒地之上":[{"id":"S01_C01","text":"54-曙光停摆于荒地之上篇：穗波往人循环、千咲处境及残星会实验已调查，同编号异数据的报告异常已有证据。"},{"id":"S01_C02","text":"54-曙光停摆于荒地之上篇：虹音塔已进入，腕表、琥珀与澄夏记录已形成求援线索，千咲的诱留场景与真实支持已区分。"},{"id":"S01_C03","text":"54-曙光停摆于荒地之上篇：本轮悲鸣循环已斩断、余念归家，内外通路已重新打开；不扩大为全部危险区往人均已消失。"},{"id":"S01_C04","text":"54-曙光停摆于荒地之上篇：千咲已离开困局并获黑海岸治疗安排；超频问题未被误写为永久治愈。"},{"id":"S02_C01","text":"55-星光流转于眼眸之间篇：千咲本阶段治疗与监测说明、二十余年时间差及当前流速趋同已交付；温暖频率补述按本人感受归因。"},{"id":"S02_C02","text":"55-星光流转于眼眸之间篇：列车长咖啡厅装饰、实际到场朋友聚会及事后交流已完成，返乡与返校计划的调整有实际依据。"},{"id":"S02_C03","text":"55-星光流转于眼眸之间篇：新裂隙缺频已检测，磁带、收音机、母亲访谈及拉海洛方向已接通，小爱声音的知情差异已保留。"}],"M20-未知的既感":[{"id":"S01_C01","text":"56-未知的既感篇：旧录取通知书与单向通道安排已交付，来客实际抵达拉海洛，个人异常空间经历按当下所知保留。"},{"id":"S01_C02","text":"56-未知的既感篇：与琳奈初遇、虚诞虫追逐已结束，二人摆脱追击并驶向学院。"},{"id":"S02_C01","text":"57-冰原下的星炬篇：登记、与千咲重逢及体检已完成，落点数日差、父母团聚结果和缺频防护上限已告知。"},{"id":"S02_C02","text":"57-冰原下的星炬篇：姓名、学部、证件照与学生证已办妥，模拟驾驶舱绑定权限及磁带、频录装置的区别已说明。"},{"id":"S02_C03","text":"57-冰原下的星炬篇：磁带刻录行程与载具安排已落实，隧者、阿列夫一及适格者训练目标已介绍。"},{"id":"S03_C01","text":"58-冰原下的星炬篇：研究院磁带刻录与检查已完成，同编码旧数据冲突、疑似删除及莫宁覆盖处理已实际经历。"},{"id":"S03_C02","text":"58-冰原下的星炬篇：人工太阳与换日准备已介绍，海维夏探测器失控已制止。"},{"id":"S03_C03","text":"58-冰原下的星炬篇：琳奈被问询后的处境及旧联络人编码异常已交付，二人决定追查，未将止险写成洗清全部嫌疑。"},{"id":"S04_C01","text":"59-冰原下的星炬篇：仪器、论文、波形与权限证据链已取得，现琳奈、原残星会身份及举报记录归属已分清。"},{"id":"S04_C02","text":"59-冰原下的星炬篇：三座防御阵列已启动，两人已毁虫体反应炉、击退袭击，仪器的改造与诱敌作用有实际记录。"},{"id":"S04_C03","text":"59-冰原下的星炬篇：救校后仪器交证与虫体回收已有结果；琳奈已被退学后获真实身份重考机会，花园交流完成，未提前记考试通过。"}],"M21-致第二次日出":[{"id":"S01_C01","text":"60-致第二次日出篇：宿舍复盘已确认琳奈重考通过；玛嘉事故与阿图雅家访已处理，日灵牧者及归源背景已了解。"},{"id":"S01_C02","text":"60-致第二次日出篇：人工磁暴装置、艾丝翠德放置证词与伊摩尔来源已调查，营地及浮光林危机均有结果。"},{"id":"S01_C03","text":"60-致第二次日出篇：伴伴与晚宴、义肢充能夜谈已交付，日树安全失效已确认，来客赴引日殿、莫宁查源的分工已开始。"},{"id":"S02_C01","text":"61-致第二次日出篇：日轮已复启，五席失能与织星危局已说明，御者授权其独担六席算量，知识及原始数据共享已落实。"},{"id":"S02_C02","text":"61-致第二次日出篇：莫宁查明污染根系诱发坠日方案与伊摩尔受利用事实，制止其继续阻拦后与来客汇合；不伪写悔悟协助。"},{"id":"S02_C03","text":"61-致第二次日出篇：魏尔伦被指认并临时剥离指挥权，莫宁与来客接手；落区疏散、校准、赫利俄斯部署和发射已执行，正式追责仍待核验。"},{"id":"S02_C04","text":"61-致第二次日出篇：发射干扰令观测失效，备用测量与近距行动已发生，莫宁独入炉芯并失联；本幕不提前记换日成功。"},{"id":"S03_C01","text":"62-致第二次日出篇：来客已追入炉芯，接手最后一程并将重伤莫宁救出。"},{"id":"S03_C02","text":"62-致第二次日出篇：赫利俄斯已恢复，第二次日出实际出现。"},{"id":"S03_C03","text":"62-致第二次日出篇：三日后探望与共同见日已完成；伪证后果、浅蓝圆环少女线索及安瑟姆证词按各自视角交付，未把少女关联错安在莫宁身上。"}],"M22-远航星":[{"id":"S01_C01","text":"63-远航星篇：爱弥斯现身、校方权限与赴冰原准备已落实，队伍已经找到天槎空间站。"},{"id":"S01_C02","text":"63-远航星篇：站内液滴紊乱、权限与转移装置已稳定，污染下层已经进入。"},{"id":"S01_C03","text":"63-远航星篇：无铭探索者已被击败并解脱；天槎录像、溯洄雨导致的时间不确定性已交付，队伍告别站内同伴并继续前往隧者沉眠地。"},{"id":"S02_C01","text":"64-远航星篇：渐湖旧屋与童年往事、卫星信息及故乡拒绝通讯已交付，辛吉勒姆来源与双方选择已揭示，夺核冲突及爱弥斯自我封闭危机已有实际应对。"},{"id":"S02_C02","text":"64-远航星篇：炉芯核心已归还隧者，爱弥斯频率完成重构并能被旁人观测；未被误写为整颗旧太阳返还或原生肉体复原。"},{"id":"S02_C03","text":"64-远航星篇：二人已经返回学院，飞行雪绒歌友会的本人演出已实际完成。"},{"id":"S03_C01","text":"65-远航星篇：虚质时空闭环、爱弥斯远行意图与坍缩期限已通过实际交流查明。"},{"id":"S03_C02","text":"65-远航星篇：渐湖追赶与超频穿行已经发生，本次未能带回成年爱弥斯的分别已明确。"},{"id":"S03_C03","text":"65-远航星篇：幼年落湖救援与护身符闭环已呈现，残留之壳经检查仅含稀薄频率，来客已回学院继续救援计划。"}],"M23-日光落处":[{"id":"S01_C01","text":"66-日光落处篇：医务室密谈、父亲空坟及会长借用身份的不死外皮线索已交付。"},{"id":"S01_C02","text":"66-日光落处篇：赫斯、校长与来客的启动隧者合作已明确，空间站救援和魏尔伦冲突已处理。"},{"id":"S01_C03","text":"66-日光落处篇：娜波摩外皮已识破、会长脱身；钢笔稷廷字符与未楹名录吻合，空白履历及推动研究的资金线已交付，未楹被确认为借用身份而非本名；旧封印破口关联仍按推测，来客保持现行救援方向。"}],"M24-影下不落的黄金":[{"id":"S01_C01","text":"67-影下不落的黄金篇：外来频率改变暗面的情况已调查，艾莉亚等被困学生已经救出。"},{"id":"S01_C02","text":"67-影下不落的黄金篇：西格莉卡面对自身期待与噩梦后已作出继续尽力、共同承担的选择。"},{"id":"S01_C03","text":"67-影下不落的黄金篇：暗面涡心已击败、权限恢复，换日庆典与伙伴合影已完成。"},{"id":"S02_C01","text":"68-影面颠倒的兔影篇：塞维的勋章记忆已调查，兔影诱导与外来暗面手段已识别。"},{"id":"S02_C02","text":"68-影面颠倒的兔影篇：来客已追入校长陷阱，洛瑟菈识破虚假剧本并保住自我与记忆能力。"},{"id":"S02_C03","text":"68-影面颠倒的兔影篇：兔影操纵关系及本次异变收束已有实际证据，操纵者借兔的交锋与下一阶段威胁已交付，队伍安全脱离；幕后实验和达妮娅关系按对应视角呈现，不强制未完成的记忆读取。"},{"id":"S03_C01","text":"69-明日摇曳的绯影篇：暗面后的校长对话已完成，残星会与最终预案的议局已交付到相应知情角色。"},{"id":"S03_C02","text":"69-明日摇曳的绯影篇：爱弥斯新频率的证据已经收到，白鸟探查结果及绯雪需休息的状态已确认，队伍进入准备期。"}],"M25-愿系铃中":[{"id":"S01_C01","text":"70-愿系铃中篇：本轮祓净、玉露频率线索及往人不同愿望已接触，活泼女性愿望接出会长的过程已呈现。"},{"id":"S01_C02","text":"70-愿系铃中篇：玉露、铃与预取代价的回忆及会长具体诱导已交付，绯雪对为人尊严的坚持与危险提案已区分。"},{"id":"S01_C03","text":"70-愿系铃中篇：本轮停在危险邀约和待选局面，未提前登记续篇告别、融合同意或尚未作出的最终选择。"}],"M26-昨夜群星":[{"id":"S01_C01","text":"71-昨夜群星篇：高压评估、御者直连及十分钟初探许可已落实；初探受阻后磁暴危机、拟制炉芯与16小时夜幕用途已明确。"},{"id":"S01_C02","text":"71-昨夜群星篇：织星校验、西格莉卡符文及分队回传已有记录；按报告核实其余队返回、十一号队体征良好并接应中的安全状态，不强加未演的返院过程；球形道标、地下地图与记忆子弹支持再次越界。"},{"id":"S01_C03","text":"71-昨夜群星篇：达妮娅已救回，绯雪特定共鸣者未来预取尽与白鸟强化已交付；先行者数据接回，爱弥斯交付拟制炉芯并用于驾驶隧者。"},{"id":"S01_C04","text":"71-昨夜群星篇：阿列夫一被放逐，隧者升格改名留守；爱弥斯完整频率与躯壳状态已确认，眺望者信号刻录、现实解析播放及善后已完成。"}],"M27-愿系铃中·续":[{"id":"S01_C01","text":"72-愿系铃中·续篇：拉海洛事件后，绯雪与玉露完成切磋、旧怨、思想变化与告别，特定共鸣者未来耗尽和自主接铃的选择已说清。"},{"id":"S01_C02","text":"72-愿系铃中·续篇：玉露已祓净，铃的终点代价已说明；会长随后告知苇原一日消失，原因仍待查，不将祝贺写成已证实交易兑现。"}],"M28-在熔解的夜空下":[{"id":"S01_C01","text":"73-在熔解的夜空下篇：限定生日出行与陪同已完成，短寿和人为生日动机、师友伤势与礼物已交付；控制书页抽取、取页后的微弱谐振恢复、仍受管制与暂禁共鸣的复查结果及未解后手已呈现。"},{"id":"S01_C02","text":"73-在熔解的夜空下篇：零点后离开、未拆抑制定位设备及克制拦截的经过已交付，旧设施记录与自主带走鸣式碎片的选择已揭示。"},{"id":"S01_C03","text":"73-在熔解的夜空下篇：来客已追到设施，收到气泡留言、重逢暗号与会长能力限制，生日遗憾及光暗回望已收束；不误判死亡或获救回校。"}],"M30-我们选择天空":[{"id":"S01_C01","text":"74-我们选择天空篇：适格者计划终止后的学生处境、机兵等研究及秋水审查已实际调查。"},{"id":"S01_C02","text":"74-我们选择天空篇：记忆宫殿中艾米娅事故与校长负疚已面对，洛瑟菈重新作出承担未知与风险的选择。"},{"id":"S01_C03","text":"74-我们选择天空篇：董事会审查已经召开，并明确批准再次挑战天空的新方向；只提出建议或开始演讲不算获批。"}],"M31-山雨欲来风满楼":[{"id":"S01_C01","text":"75-山雨欲来风满楼篇：秧秧来信与玄方袭击、炽霞重伤的前情已交付，来客已从学院回到今州取得边庭授权。"},{"id":"S01_C02","text":"75-山雨欲来风满楼篇：梦窟及井栈调查已实际推进，来客与穗穗失散但已通过装置确认体征仍正常。"},{"id":"S01_C03","text":"75-山雨欲来风满楼篇：椋羽接应和机傀异常情况已说明，巡霄环与云帛机骑权限已接入，秧秧战斗残影已显现。"},{"id":"S02_C01","text":"76-山雨欲来风满楼篇：秧秧获救入村、青彦寻剑及旧剑托付的回述已实际展开。"},{"id":"S02_C02","text":"76-山雨欲来风满楼篇：救民、测绘撤离、前营留信与定玄卫诱敌的行动已经交付，不只停在村内交谈。"},{"id":"S02_C03","text":"76-山雨欲来风满楼篇：秧秧已经历木禺展示的渊城旧战并拒绝其歪曲牺牲的论断，仍陷危险的状态与留下的追踪线索已明确。"}],"M32-玄翎振壑定澜音":[{"id":"S01_C01","text":"77-玄翎振壑定澜音篇：悬天构实验记录和被捕平民用途已查明，平民已从咎笼救出。"},{"id":"S01_C02","text":"77-玄翎振壑定澜音篇：万囮牢已被击败、相应屏障已解除，秧秧已经救回并获护送进城安排。"},{"id":"S01_C03","text":"77-玄翎振壑定澜音篇：穗穗与心的试炼和新交易已通过回叙交付，分散的队伍已实际重聚。"},{"id":"S02_C01","text":"78-玄翎振壑定澜音篇：木禺可能化名沈渊的情报已汇报，收容平民、停用不明机傀及通讯布防已落实。"},{"id":"S02_C02","text":"78-玄翎振壑定澜音篇：本轮玄方攻城已守住，清宵、椋羽等完成接防，来客与秧秧已追入咎庭。"},{"id":"S02_C03","text":"78-玄翎振壑定澜音篇：千傀重楼已被击败、受困众声得到解脱，玄翎传承与当前城防结果已实际呈现。"},{"id":"S03_C01","text":"79-玄翎振壑定澜音篇：秋鸿已说明椋羽治疗和机傀隔离现状，战后不被误当全部恢复原样。"},{"id":"S03_C02","text":"79-玄翎振壑定澜音篇：与白芷、相里要的平安联络已完成，炽霞康复及宿镜后续疑问已交换。"},{"id":"S03_C03","text":"79-玄翎振壑定澜音篇：今汐与秋鸿已知晓后续行动，漂泊者与秧秧决定暂留玄方追查岁主。"},{"id":"S04_C01","text":"80-灵籁之契冥相因篇：两日后的秧秧复查已完成，新能力范围及无玄翎样本的限制已说明。"},{"id":"S04_C02","text":"80-灵籁之契冥相因篇：海螺与云陵谷相遇的记忆段已交付，报告已允许其到军策府报到。"},{"id":"S04_C03","text":"80-灵籁之契冥相因篇：秧秧已亲口表达现在同行的愿望，伙伴康复消息已收到；不替玩家承诺恋爱或永不分离。"}],"M33-烟云幽远心剑鸣":[{"id":"S01_C01","text":"81-烟云幽远心剑鸣篇：穗穗已离开，雾隐阁禁制失效及咎庭、四鸣井异常已查明。"},{"id":"S01_C02","text":"81-烟云幽远心剑鸣篇：清宵剑阵、飞舟疏散及军策府收容已实施，守城和查神宫的分工已明确。"},{"id":"S01_C03","text":"81-烟云幽远心剑鸣篇：青蚨挂饰已打开神宫通路，景燃暗留接应线索已读出，来客与清宵已因城体异变坠入深谷。"},{"id":"S02_C01","text":"82-烟云幽远心剑鸣篇：旧城未败亡与现实惨史的矛盾已识别，人境云梭的御剑路径已实际通过。"},{"id":"S02_C02","text":"82-烟云幽远心剑鸣篇：鬼界寄魂机傀、残响停机与木禺试验记录已调查，不能把它们当真实无损复生。"},{"id":"S02_C03","text":"82-烟云幽远心剑鸣篇：景燃的寻幽记和守玄机铳已取得，二人已上大型云梭暂歇，清宵消耗失稳的状态已呈现。"},{"id":"S03_C01","text":"83-烟云幽远心剑鸣篇：清宵心魔内景中的修行、入世及云渊无可两全已面对，二人完成互相扶持后脱出内景。"},{"id":"S03_C02","text":"83-烟云幽远心剑鸣篇：景燃会合、云梭主舰攻防及征天机枢已解决，小玉的若云身份与自愿化天人旧事已揭明。"},{"id":"S03_C03","text":"83-烟云幽远心剑鸣篇：木禺天傀劫煞两阶段战斗已结束，众生心剑依各人守护意志起效，实验残响得到保护；荡除恶念与抵挡天崩的收束行动已完成。"},{"id":"S03_C04","text":"83-烟云幽远心剑鸣篇：队伍已返回园林，心实际现身说明中枢崩毁并承接后果，玄方进入修复。"},{"id":"S04_C01","text":"84-烟云幽远心剑鸣篇：穗穗的战后情报已交流，组织余线与当前已解决危机已区分。"},{"id":"S04_C02","text":"84-烟云幽远心剑鸣篇：道馆师徒邀约及剑符已交付，来客对是否延续关系有回应或明确暂不决定的空间。"},{"id":"S04_C03","text":"84-烟云幽远心剑鸣篇：御剑赴城与渊中鲜用餐已完成；静微收徒回忆、玄渺真人与长离来访及乘霄山设局损寿的旧事已区分交付，小玉平安讯息已收到，日常段收束。"},{"id":"S05_C01","text":"85-幽客销残声篇：烟舒与椋羽的寻人线索已落实，来客已和景燃实际见面。"},{"id":"S05_C02","text":"85-幽客销残声篇：景燃父母、刃偶事故与寻幽卧底动机已讲明；木禺逃逸残响被追上了结、岁主数据核心及遗留物处理、吟霖据手稿密信收网和锁暝另行岁主事务，按各自视角实际交付，不要求来客当场知晓全部幕后。"},{"id":"S05_C03","text":"85-幽客销残声篇：清宵另赠成对古琴及教琴意愿的飞讯已交付，本轮玄方余波已收束。"}],"M34-梦枢心相由心生":[{"id":"S01_C01","text":"86-梦枢心相由心生篇：神宫心相迷宫、烬心域月灯覆写及锁暝怡心域的调查已实际完成。"},{"id":"S01_C02","text":"86-梦枢心相由心生篇：凄心域旧事与云渊选择已交付，心已坦白本体消逝及自我牺牲计划，并选择不以自毁逃避。"},{"id":"S01_C03","text":"86-梦枢心相由心生篇：承载原岁主最后频率的玄朱锁已由心开启、道歉与认可已交付，天演溯心及分形被击败，文明之匣新规则已落实。"},{"id":"S01_C04","text":"86-梦枢心相由心生篇：玄方崩落已止住，近消散天人已收容进宿镜，心保留自我且朝月会具备举行条件。"},{"id":"S02_C01","text":"87-梦枢心相由心生篇：已确认玄方城保留下来，心对天罗狐影与留守天人的内部收尾安排已说明。"},{"id":"S02_C02","text":"87-梦枢心相由心生篇：锁暝已将神宫修缮和天罗入口交接给砌庭、砌凌，来客已赴约与心进入朝月会。"},{"id":"S03_C01","text":"88-梦枢心相由心生·后日谈篇：朝月会中与锁暝、心的灯下交流及共同赴会已经实际完成。"},{"id":"S03_C02","text":"88-梦枢心相由心生·后日谈篇：玄朱锁六契、八契回响的释放及未定代价已说明，并与锦妙锁分形权能区分；赴梦州人员线索、组织与明庭未结事项、卫星及稷廷文字协查无果、残缺记忆交黑海岸的安排按实际交谈交付。"},{"id":"S03_C03","text":"88-梦枢心相由心生·后日谈篇：本轮节日与守护者休息已经收束；所附参考卡补充的《璇心如月寄尘情》独立可选，不自动接取，也不虚构其后的新篇。"}],"M36-璇心如月寄尘情":[{"id":"S01_C01","text":"91-璇心如月寄尘情篇：情匣碎片、屯屯留下的力量与心钥井入口均已处理，记忆修复已实际开始。"},{"id":"S01_C02","text":"91-璇心如月寄尘情篇：三处混乱频率的修复已展开，乡村相识、香囊与隘口二次共鸣的缘由和代价已经揭明。"},{"id":"S01_C03","text":"91-璇心如月寄尘情篇：虚构玄方城、真实建城历史与墟心域已区分，云梭受阻及最后情感的来源已经说明。"},{"id":"S01_C04","text":"91-璇心如月寄尘情篇：情匣已按实际选择交付给心或形成有依据的等效结果，璇情的录像、最后问候与“被选择的人性”已传达。"},{"id":"S01_C05","text":"91-璇心如月寄尘情篇：璇情与墟心域的道别已收束，遗落物去向如实交代；不把记忆、录像或残频当作现实复活。"}]},"鸣潮伴星任务":{"此际我独行":[{"id":"C01","text":"互助会成员、父母旧档与偃师实验目的的证据已取得，吟霖立场已在实际对峙中揭明。"},{"id":"C02","text":"偃师与聚械机偶已被实际制止，三类工厂证据与受害者已移交；录口供后礼荣已醒但仍有严重后遗症的诊察结果已交付。"},{"id":"C03","text":"与吟霖的事后会面已完成，利用、信任及继续追查残星会的安排已交流；档案被删、身份无法证明与暂须保密的处境已说明，未强行恢复身份或唤醒媛媛。"}],"离火弈长生":[{"id":"C01","text":"梧黎已获救，伏翎的真实愿望与残星会引导寻棋的证据已调查。"},{"id":"C02","text":"蜃境幼时长离、师父旧缘及双视角路径已展开，二人以可控离火破局平安脱困；已区分幼时不可逆的损寿与当下用火不再新增同类反噬。"},{"id":"C03","text":"出境近五日后的善后、山中残党被捕与受伤会监逃逸、梧黎伏翎继续旅行和名医联络均已交付；随后两日对谈说明传说与棋局后手，并完成续棋收束。"}],"自问丹青":[{"id":"C01","text":"画室、造假仓库、原稿、交易签名及两份不同录音的证据链已取得；已区分夜间终端自录与仓库装置中的死亡威胁，不能只凭掉色断定全部罪行。"},{"id":"C02","text":"治安署论辩已公开原作者并经历无生画境，山云阁责任与明砚重审安排已落定。"},{"id":"C03","text":"事后探望明砚、归还其初见时赠给折枝的旧画及误认后重新面对自我的转折已交付，折枝接受过去、继续创作与表达友谊的变化已呈现。"}],"小小羊咩大冒险":[{"id":"C01","text":"现实寻宝已取得剑和盾，枯花田与两位孩子思念母亲的原因已揭明。"},{"id":"C02","text":"已向维里奈明确普通花与共鸣造物均不能完成永生花要求，制成感受花冠并留空；小盈表达鸢尾心愿、愿意相信与续行，次日下午第二次冒险已实际完成。"},{"id":"C03","text":"愿望门、魔王战与鸢尾表达已完成，众人回到现实、小盈交出希望花冠并告别；没有将幻想相见记成现实复活，木剑木盾去向也未混淆。"}],"小径分岔的星海":[{"id":"C01","text":"花女遗留物、先撤回来客而椿仍被困的首次下潜意外、对称星图救援及三处分岔已揭明；第三处少量幸存与花树救村是正确历史基准，主动封忆原因已按证据交付。"},{"id":"C02","text":"当前椿与来客已实际会合并击败星图核心（心魔），错误星图坐标已经交付回收，守岸人要求椿到医疗舱报到的善后已说明；未以此推定根源治愈。"},{"id":"C03","text":"沉雾岩拍照及手链、当下记忆的最后交流已完成，不要求强行恢复所有记忆。"}],"如果在雨夜，一个家族":[{"id":"C01","text":"贝内特被杀、数据元件去向与科波拉交易的完整证据已复原。"},{"id":"C02","text":"珂莱塔已自主离开镜中领域，与来客落实两日后的交易截断及接应方案。"},{"id":"C03","text":"交易实际破裂、数据元件回安全区、老邓肯获得接应，科波拉及手下受家族审判的安排已宣布；雨中责任与猫眼石真实指代物赠礼已交付，未把临时身份直接转成正式入家族或继位。"}],"今夜星光灿烂":[{"id":"C01","text":"船葬滩幸存者的救援、照料及遗物收集已完成，卢卡的星星已经找回。"},{"id":"C02","text":"迷宫布偶已被制止并接纳回剧团，主人保护真相及四个布偶分别找回主人或遗物的结果已交付；未将所有主人判死。"},{"id":"C03","text":"新编演出完成，改用的琴、枪、花环分别归还，卢卡星星经同意借用后归还且不强制她登台；海萤石礼物与互助已交付，玩家入团邀请可拒绝，不以入团作通关前提。"}],"幽夜幻梦":[{"id":"C01","text":"三处谜面与八音盒、齿轮硬币、红帽人偶组合及桂冠演奏已实际完成；幽灵之海毒物试炼、替代少女与安妮斯引路身份已通过探索揭开。"},{"id":"C02","text":"老家主异化执念已化解，切里等生还者与亡者残频已区分，宅邸当前囚笼已解除。"},{"id":"C03","text":"桂冠协助生还少女安全归乡的安排、告别与夜谈已完成，阿布醒来确认邮件异常频率影响消失；不以安神暂缓代替解除，也不以真实复活解释秘药。"}],"夜行的焰光":[{"id":"C01","text":"旧入口、夜行者身份、柯琳被胁迫情况与终端疑点已调查。"},{"id":"C02","text":"中间人已被控制并交出新入口，队伍实际进入废弃水道，柯琳须如实交代参与犯罪的责任已说明。"},{"id":"C03","text":"本卡补写的新任塔洛斯首领战已实际展开并使其失去威胁能力，人形交锋与声骸拟态或有效阻止拟态的结果已交付；终端已隔离、居民安全与首领移交或实际改写去向已明确。"},{"id":"C04","text":"首领受制及救援后，赞妮关于日常与善意的事后交流和旧武器承诺已发生；没有以赠物、进入水道或预定结局冒充首领战胜利。"}],"边缘幻梦":[{"id":"C01","text":"门扉异常已调查，露西与丽贝卡获救，跨界与梦境经历已通过实际交流确认。"},{"id":"C02","text":"学院遇袭、学生救援与幻梦频段解析已处理；样本研究、武器远程适配及实际生效已有记录，同频防御分工已落实。"},{"id":"C03","text":"幻梦频段已收集并唤醒梦中大卫，露西已面对现实死亡与梦魇恐惧，终点的梦魇亚当·重锤已被击败。"},{"id":"C04","text":"同伴告别或有依据的改写去向已落实，学院逸散频率清理与空间恢复已有确认。"},{"id":"C05","text":"露西自主返回原世界及醒来已交付，或玩家改写后的长期去向与两界后果已实际收束。"}],"唯你的长夏永不凋落":[{"id":"S01_C01","text":"89-唯你的长夏永不凋落·上篇：餐馆袭击已处理，死亡乐谱的来历及寻找夏空的理由已交付。"},{"id":"S01_C02","text":"89-唯你的长夏永不凋落·上篇：水畔重奏已区分流言与作者原声，珂莱塔留城与二人赴海滩的分工已经落实。"},{"id":"S01_C03","text":"89-唯你的长夏永不凋落·上篇：安魂乐园的残琴记忆已调查，诗人审判与童年片段分别呈现，并已安全回到现实。新增全文的唱诗班、莱莎排练与赞歌起源线索也已处理，下一步拂风水畔骑士营地的调查方向已明确。"},{"id":"S02_C01","text":"90-唯你的长夏永不凋落·下篇：天马浮雕与火灾记忆均已调查，已区分现实物证、遗落乐谱和记忆中的黄铜钥匙。新增全文的采风石板、返回餐厅公开说明、珂莱塔查证与港口遗落乐谱内心片段也已按实际调查交付。"},{"id":"S02_C02","text":"90-唯你的长夏永不凋落·下篇：与夏空的崖边交流已实际展开，她对继续演出的选择或有依据的改写方向已经形成。"},{"id":"S02_C03","text":"90-唯你的长夏永不凋落·下篇：剧院公开演出与追捕危机已解决，夏空和来客已安全撤离或产生明确的改写后果。"},{"id":"S02_C04","text":"90-唯你的长夏永不凋落·下篇：事后乐谱赠礼的接收安排、歌曲约定及夏空去向已交代，幕后片段未变成现场角色知识。"}]}},"SOLARIS_MERGED_GROUPS":[{"name":"M01-万象新声·上","parts":["01-万象新声·上篇","