  const getNames=lookup('getCharWorldbookNames'),getBook=lookup('getWorldbook');if(!getNames||!getBook)return fallback;
  const bookName=getNames('current')?.primary;if(!bookName)return fallback;const book=await getBook(bookName);
  const entry=book.find(e=>(e.name||e.comment)==='鸣潮主线控制器【鸣潮·细纲版】');if(!entry)return fallback;
  const next={...fallback};for(const key of ['END_MANIFEST','SOLARIS_MERGED_GROUPS','SOLARIS_LEGACY_END','SOLARIS_GROUP_RENAMES']){
   const match=String(entry.content||'').match(new RegExp('const '+key+'\\s*=\\s*(\\{[\\s\\S]*?\\}|\\[[\\s\\S]*?\\]);'));if(!match)return fallback;next[key]=JSON.parse(match[1]);
